import AppKit
import Foundation

/// omaflake icons for the app, the runner and QEMU windows. The PNG data lives in
/// BrandAssets.swift, generated by brand/generate.py (edit the generator, not the data).
public enum Brand {
    /// App icon (512 px): Dock icon of omaf-runner, source of QEMU's Dock icon.
    public static func appIcon() -> NSImage? {
        decode(BrandAssets.appIcon512).flatMap { NSImage(data: $0) }
    }

    /// Menu bar template image, 18 pt with 1x/2x/3x representations; macOS tints it.
    public static func menuBarImage() -> NSImage {
        let image = NSImage(size: NSSize(width: 18, height: 18))
        for data in [BrandAssets.menuBar1x, BrandAssets.menuBar2x, BrandAssets.menuBar3x].compactMap(decode) {
            guard let rep = NSBitmapImageRep(data: data) else { continue }
            rep.size = image.size
            image.addRepresentation(rep)
        }
        image.isTemplate = true
        image.accessibilityDescription = "omaflake"
        return image
    }

    /// App icon as a file for QEMU's Dock icon (OMAFLAKE_DOCK_ICON, patch qemu-cocoa-dock-icon): the app writes it to
    /// `<data folder>/cache/dock-icon.png`, where the Rust core looks for it (`Paths::dock_icon`); rewritten when it
    /// differs.
    public static func writeDockIcon(to url: URL) throws {
        guard let data = decode(BrandAssets.appIcon512) else { throw VMError("Embedded app icon is not valid base64") }
        if (try? Data(contentsOf: url)) != data {
            try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try data.write(to: url, options: .atomic)
        }
    }

    static func decode(_ base64: String) -> Data? {
        Data(base64Encoded: base64, options: .ignoreUnknownCharacters)
    }
}
